from pysat.solvers import Glucose4
from itertools import combinations

# 12 vertices, labels 0..26
# 26 edges, labels 1..26

def v_var(i, l):
    return i * 27 + l + 1

def e_var(idx, d):
    return 12 * 27 + idx * 26 + d

edges = []
for g in range(3):
    for i in range(4):
        for j in range(i + 1, 4):
            edges.append((g * 4 + i, g * 4 + j))

for g in range(2):
    for i in range(4):
        edges.append((g * 4 + i, (g + 1) * 4 + i))

solver = Glucose4()

# Each vertex has exactly one label
for i in range(12):
    solver.add_clause([v_var(i, l) for l in range(27)])
    for l1 in range(27):
        for l2 in range(l1 + 1, 27):
            solver.add_clause([-v_var(i, l1), -v_var(i, l2)])

# Distinct vertex labels
for l in range(27):
    for i in range(12):
        for j in range(i + 1, 12):
            solver.add_clause([-v_var(i, l), -v_var(j, l)])

# Each edge has exactly one label
for idx in range(26):
    solver.add_clause([e_var(idx, d) for d in range(1, 27)])
    for d1 in range(1, 27):
        for d2 in range(d1 + 1, 27):
            solver.add_clause([-e_var(idx, d1), -e_var(idx, d2)])

# Distinct edge labels
for d in range(1, 27):
    for idx1 in range(26):
        for idx2 in range(idx1 + 1, 26):
            solver.add_clause([-e_var(idx1, d), -e_var(idx2, d)])

# Edge label definition
for idx, (u, v) in enumerate(edges):
    for l1 in range(27):
        for l2 in range(27):
            if l1 != l2:
                d = abs(l1 - l2)
                # if u has l1 and v has l2, then edge idx has label d
                solver.add_clause([-v_var(u, l1), -v_var(v, l2), e_var(idx, d)])

# Symmetry breaking
# V[0] < V[1] < V[2] < V[3]
for l1 in range(27):
    for l2 in range(l1 + 1):
        solver.add_clause([-v_var(0, l1), -v_var(1, l2)])
        solver.add_clause([-v_var(1, l1), -v_var(2, l2)])
        solver.add_clause([-v_var(2, l1), -v_var(3, l2)])

# V[0] < V[8]
for l1 in range(27):
    for l2 in range(l1 + 1):
        solver.add_clause([-v_var(0, l1), -v_var(8, l2)])

# V[0] <= 13
for l in range(14, 27):
    solver.add_clause([-v_var(0, l)])

if solver.solve():
    model = solver.get_model()
    labels = [-1] * 12
    for i in range(12):
        for l in range(27):
            if v_var(i, l) in model:
                labels[i] = l
    print(labels)
else:
    print("UNSAT")
